const getCarById = (id) => {
    return exports.cars.find(car => car.id === id);
};
exports.getCarById = getCarById;
const getExclusiveCars = () => {
    return exports.cars.filter(car => car.isExclusive);
};
exports.getExclusiveCars = getExclusiveCars;
const getCarsByBrand = (brand) => {
    return exports.cars.filter(car => car.brand.toLowerCase() === brand.toLowerCase());
};
exports.getCarsByBrand = getCarsByBrand;
const getCarsByPriceRange = (min, max) => {
    return exports.cars.filter(car => car.price >= min && car.price <= max);
};
exports.getCarsByPriceRange = getCarsByPriceRange;
const getCarsByCondition = (condition) => {
    return exports.cars.filter(car => car.condition === condition);
};
exports.getCarsByCondition = getCarsByCondition;
